/** The calls Go makes of the host, on the UI thread. */
interface HostCalls {
    /** the app's bundle and the system's settings, asked once at start */
    fun appInfo(): AppInfoReply
    /** the name of the system's time zone; any thread */
    fun timeZone(): TimeZoneReply
    /** the appearance and the accessibility preferences */
    fun theme(): ThemeReply
    /** the appearance the app asks for: "light", "dark" or "system" */
    fun setAppearance(c: SetAppearanceCall)
    /** the Wi-Fi multicast lock the local network's discovery holds, or gives back */
    fun multicastLock(c: MulticastLockCall)
    /** the screen's size in DIPs and scale */
    fun screen(): ScreenReply
    /** a line the app wrote to its standard output or error */
    fun log(c: LogCall)
    /** the screen's content: a web view, or a surface for native UI */
    fun createWindow(c: CreateWindowCall): CreateWindowReply
    /** the window's content presented its first frame */
    fun firstFrame(c: FirstFrameCall)
    /** where a surface shows the windows it holds (Parent), under it, in the order painted; the others hide. Places: encoded by Go (encodePlaces) */
    fun placeViews(c: PlaceViewsCall)
    fun showWindow(c: ShowWindowCall)
    fun hideWindow(c: HideWindowCall)
    fun closeWindow(c: CloseWindowCall)
    fun setBackground(c: SetBackgroundCall)
    fun focus(c: FocusCall)
    /** the window's title, which a navigation bar shows */
    fun setTitle(c: SetTitleCall)
    /** a bar of tabs, whose tabs AddTab adds before ShowTabs shows it */
    fun createTabs(c: CreateTabsCall)
    fun addTab(c: AddTabCall)
    fun showTabs(c: ShowTabsCall)
    fun selectTab(c: SelectTabCall)
    fun setTabBadge(c: SetTabBadgeCall)
    fun closeTabs(c: CloseTabsCall)
    /** shows Child over Parent in Parent's stack, under a bar with its Title and a back button */
    fun pushWindow(c: PushWindowCall)
    fun popWindow(c: PopWindowCall)
    fun loadURL(c: LoadURLCall)
    fun loadHTML(c: LoadHTMLCall)
    fun reload(c: ReloadCall)
    fun stopLoading(c: StopLoadingCall)
    fun goBack(c: GoBackCall)
    fun goForward(c: GoForwardCall)
    fun eval(c: EvalCall)
    /** runs Body as an async function's; AsyncResult answers */
    fun callAsync(c: CallAsyncCall)
    fun setZoom(c: SetZoomCall)
    fun setUserAgent(c: SetUserAgentCall)
    fun setUserScripts(c: SetUserScriptsCall)
    /** a PNG of the page; Captured answers */
    fun capturePage(c: CapturePageCall)
    fun userAgent(c: UserAgentCall): UserAgentReply
    /** the status and headers of a SchemeRequest (Header: names and values in turn) */
    fun schemeRespond(c: SchemeRespondCall)
    fun schemeData(c: SchemeDataCall)
    fun schemeFinish(c: SchemeFinishCall)
    fun schemeFail(c: SchemeFailCall)
    /** an alert; MessageBoxResult answers */
    fun messageBox(c: MessageBoxCall)
    /** the system's picker of documents; FilesResult answers with copies the app may read */
    fun openFiles(c: OpenFilesCall)
    /** the share sheet of a file, as the place to save it */
    fun shareFile(c: ShareFileCall)
    fun clipboardText(): ClipboardTextReply
    fun setClipboardText(c: SetClipboardTextCall)
    /** opens a URL in the app the system has for it */
    fun openURL(c: OpenURLCall): OpenURLReply
    fun secretGet(c: SecretGetCall): SecretGetReply
    fun secretSet(c: SecretSetCall): SecretSetReply
    fun secretDelete(c: SecretDeleteCall): SecretDeleteReply
    /** a local notification; NotifyDone answers once the system has it */
    fun notify(c: NotifyCall)
    fun removeNotification(c: RemoveNotificationCall)
    fun removeAllNotifications()
    /** keeps the screen on while the app shows */
    fun keepAwake(c: KeepAwakeCall)
    fun networkStatus(): NetworkStatusReply
    /** starts NetworkChanged */
    fun watchNetwork()
    fun battery(): BatteryReply
    /** the icons of the system's bars ("auto", "light" or "dark"), and whether the bars hide */
    fun setSystemBars(c: SetSystemBarsCall)
    /** the orientations the screen may take: 1 portrait, 2 upside down, 4 landscape left, 8 landscape right; 0 any */
    fun setOrientations(c: SetOrientationsCall)
    /** the share sheet of text, a link and files; ShareResult answers */
    fun share(c: ShareCall)
    /** the system's picker of where to keep a copy of Path under Name; FilesResult answers with the place, empty when dismissed */
    fun saveFile(c: SaveFileCall)
    fun clipboardImage(): ClipboardImageReply
    fun setClipboardImage(c: SetClipboardImageCall)
    /** the system's menu at a point of the window: Items are encoded by Go (encodeMenu); MenuPicked answers with the item's ID, 0 when dismissed */
    fun popupMenu(c: PopupMenuCall)
    /** the buttons at the end of the window's navigation bar; BarItemClicked tells which: titles, symbols and icons by index */
    fun setBarItems(c: SetBarItemsCall)
    /** a call of a plugin's native code: Args and PluginResult's Result are JSON */
    fun pluginCall(c: PluginCallCall)
    /** opens the sound's output: stereo at Rate frames a second, holding about Ahead milliseconds; on the caller's thread */
    fun audioOpen(c: AudioOpenCall): AudioOpenReply
    /** plays interleaved stereo float32 samples after those written, waiting while the output holds enough; on the caller's thread */
    fun audioWrite(c: AudioWriteCall): AudioWriteReply
    fun audioClose(): AudioCloseReply
    /** "selection", "light", "medium", "heavy", "success", "warning" or "error" */
    fun haptic(c: HapticCall)
    /** asks for a Frame at the next refresh of the display */
    fun requestFrame(c: RequestFrameCall)
    /** whether the keyboard shows and what for: the input's traits (platform.TextTraits), and its text. Show counts the requests to show the keyboard again. Offsets are UTF-16 units of the document, of which Text is the part around the selection, from Base; MarkStart is -1 without marked text. A window without Document takes text without one, as a terminal: the keyboard sees none */
    fun setTextInput(c: SetTextInputCall)
    /** the pointer's shape, for a mouse or a trackpad */
    fun setCursor(c: SetCursorCall)
    /** the tree of accessible elements changed; Focus names the one with the focus */
    fun accessibilityChanged(c: AccessibilityChangedCall)
    fun announce(c: AnnounceCall)
    /** the system's edit menu at a point, with the actions given (cut, copy, paste, selectAll); TextCommand answers */
    fun showMenu(c: ShowMenuCall)
    /** whether the content takes the system's back */
    fun setBackAvailable(c: SetBackAvailableCall)
    /** the system's magnifier of what is at a point */
    fun showMagnifier(c: ShowMagnifierCall)
    fun hideMagnifier(c: HideMagnifierCall)
    /** the metrics of a font (Android's Paint): ascent and descent, x-height, underline and strikethrough */
    fun textMetrics(c: TextMetricsCall): TextMetricsReply
    /** how wide each of Texts is in a font, kerned unless NoKern */
    fun measureText(c: MeasureTextCall): MeasureTextReply
    /** the advance of each UTF-16 unit of Text laid out as a whole (getTextRunAdvances) */
    fun textAdvances(c: TextAdvancesCall): TextAdvancesReply
    /** draws Text in white at Scale pixels per DIP, its pen DX pixels right of a pixel's edge: its ink's box from the pen and its pixels, a byte of coverage each, or premultiplied RGBA when Color */
    fun drawText(c: DrawTextCall): DrawTextReply
    /** adds a font file under Family, or its own family when empty */
    fun registerFont(c: RegisterFontCall): RegisterFontReply
}

/** Runs a call on h and encodes its reply, null for a call not waited for. */
fun dispatchCall(h: HostCalls, buf: ByteArray): ByteArray? {
    val r = WireReader(buf)
    val w = WireWriter()
    when (r.uvarint().toInt()) {
        1 -> { h.appInfo().encode(w); return w.toByteArray() }
        2 -> { h.timeZone().encode(w); return w.toByteArray() }
        3 -> { h.theme().encode(w); return w.toByteArray() }
        4 -> h.setAppearance(SetAppearanceCall(r))
        5 -> h.multicastLock(MulticastLockCall(r))
        6 -> { h.screen().encode(w); return w.toByteArray() }
        7 -> h.log(LogCall(r))
        8 -> { h.createWindow(CreateWindowCall(r)).encode(w); return w.toByteArray() }
        9 -> h.firstFrame(FirstFrameCall(r))
        10 -> h.placeViews(PlaceViewsCall(r))
        11 -> h.showWindow(ShowWindowCall(r))
        12 -> h.hideWindow(HideWindowCall(r))
        13 -> h.closeWindow(CloseWindowCall(r))
        14 -> h.setBackground(SetBackgroundCall(r))
        15 -> h.focus(FocusCall(r))
        16 -> h.setTitle(SetTitleCall(r))
        17 -> h.createTabs(CreateTabsCall(r))
        18 -> h.addTab(AddTabCall(r))
        19 -> h.showTabs(ShowTabsCall(r))
        20 -> h.selectTab(SelectTabCall(r))
        21 -> h.setTabBadge(SetTabBadgeCall(r))
        22 -> h.closeTabs(CloseTabsCall(r))
        23 -> h.pushWindow(PushWindowCall(r))
        24 -> h.popWindow(PopWindowCall(r))
        25 -> h.loadURL(LoadURLCall(r))
        26 -> h.loadHTML(LoadHTMLCall(r))
        27 -> h.reload(ReloadCall(r))
        28 -> h.stopLoading(StopLoadingCall(r))
        29 -> h.goBack(GoBackCall(r))
        30 -> h.goForward(GoForwardCall(r))
        31 -> h.eval(EvalCall(r))
        32 -> h.callAsync(CallAsyncCall(r))
        33 -> h.setZoom(SetZoomCall(r))
        34 -> h.setUserAgent(SetUserAgentCall(r))
        35 -> h.setUserScripts(SetUserScriptsCall(r))
        36 -> h.capturePage(CapturePageCall(r))
        37 -> { h.userAgent(UserAgentCall(r)).encode(w); return w.toByteArray() }
        38 -> h.schemeRespond(SchemeRespondCall(r))
        39 -> h.schemeData(SchemeDataCall(r))
        40 -> h.schemeFinish(SchemeFinishCall(r))
        41 -> h.schemeFail(SchemeFailCall(r))
        42 -> h.messageBox(MessageBoxCall(r))
        43 -> h.openFiles(OpenFilesCall(r))
        44 -> h.shareFile(ShareFileCall(r))
        45 -> { h.clipboardText().encode(w); return w.toByteArray() }
        46 -> h.setClipboardText(SetClipboardTextCall(r))
        47 -> { h.openURL(OpenURLCall(r)).encode(w); return w.toByteArray() }
        48 -> { h.secretGet(SecretGetCall(r)).encode(w); return w.toByteArray() }
        49 -> { h.secretSet(SecretSetCall(r)).encode(w); return w.toByteArray() }
        50 -> { h.secretDelete(SecretDeleteCall(r)).encode(w); return w.toByteArray() }
        51 -> h.notify(NotifyCall(r))
        52 -> h.removeNotification(RemoveNotificationCall(r))
        53 -> h.removeAllNotifications()
        54 -> h.keepAwake(KeepAwakeCall(r))
        55 -> { h.networkStatus().encode(w); return w.toByteArray() }
        56 -> h.watchNetwork()
        57 -> { h.battery().encode(w); return w.toByteArray() }
        58 -> h.setSystemBars(SetSystemBarsCall(r))
        59 -> h.setOrientations(SetOrientationsCall(r))
        60 -> h.share(ShareCall(r))
        61 -> h.saveFile(SaveFileCall(r))
        62 -> { h.clipboardImage().encode(w); return w.toByteArray() }
        63 -> h.setClipboardImage(SetClipboardImageCall(r))
        64 -> h.popupMenu(PopupMenuCall(r))
        65 -> h.setBarItems(SetBarItemsCall(r))
        66 -> h.pluginCall(PluginCallCall(r))
        67 -> { h.audioOpen(AudioOpenCall(r)).encode(w); return w.toByteArray() }
        68 -> { h.audioWrite(AudioWriteCall(r)).encode(w); return w.toByteArray() }
        69 -> { h.audioClose().encode(w); return w.toByteArray() }
        70 -> h.haptic(HapticCall(r))
        71 -> h.requestFrame(RequestFrameCall(r))
        72 -> h.setTextInput(SetTextInputCall(r))
        73 -> h.setCursor(SetCursorCall(r))
        74 -> h.accessibilityChanged(AccessibilityChangedCall(r))
        75 -> h.announce(AnnounceCall(r))
        76 -> h.showMenu(ShowMenuCall(r))
        77 -> h.setBackAvailable(SetBackAvailableCall(r))
        78 -> h.showMagnifier(ShowMagnifierCall(r))
        79 -> h.hideMagnifier(HideMagnifierCall(r))
        80 -> { h.textMetrics(TextMetricsCall(r)).encode(w); return w.toByteArray() }
        81 -> { h.measureText(MeasureTextCall(r)).encode(w); return w.toByteArray() }
        82 -> { h.textAdvances(TextAdvancesCall(r)).encode(w); return w.toByteArray() }
        83 -> { h.drawText(DrawTextCall(r)).encode(w); return w.toByteArray() }
        84 -> { h.registerFont(RegisterFontCall(r)).encode(w); return w.toByteArray() }
    }
    return null
}

/** Encodes the events the host sends Go. */
object Event {
    /** the app finished launching */
    @JvmStatic fun ready(): ByteArray {
        val w = WireWriter()
        w.uvarint(1)
        return w.toByteArray()
    }
    /** the app is in front, or no longer */
    @JvmStatic fun active(active: Boolean): ByteArray {
        val w = WireWriter()
        w.uvarint(2)
        w.bool(active)
        return w.toByteArray()
    }
    /** the app goes to the background (true) or came back. The host waits: iOS ends apps that use the GPU in the background, so that frames stop before it returns */
    @JvmStatic fun background(background: Boolean): ByteArray {
        val w = WireWriter()
        w.uvarint(3)
        w.bool(background)
        return w.toByteArray()
    }
    @JvmStatic fun themeChanged(): ByteArray {
        val w = WireWriter()
        w.uvarint(4)
        return w.toByteArray()
    }
    @JvmStatic fun localeChanged(): ByteArray {
        val w = WireWriter()
        w.uvarint(5)
        return w.toByteArray()
    }
    @JvmStatic fun timeZoneChanged(id: String): ByteArray {
        val w = WireWriter()
        w.uvarint(6)
        w.string(id)
        return w.toByteArray()
    }
    @JvmStatic fun openURLs(urls: List<String>): ByteArray {
        val w = WireWriter()
        w.uvarint(7)
        w.strings(urls)
        return w.toByteArray()
    }
    @JvmStatic fun memoryWarning(): ByteArray {
        val w = WireWriter()
        w.uvarint(8)
        return w.toByteArray()
    }
    /** the process ends once Go answers */
    @JvmStatic fun terminating(): ByteArray {
        val w = WireWriter()
        w.uvarint(9)
        return w.toByteArray()
    }
    /** the window's size in DIPs, the scale, and the insets of what covers it: the system's bars, the cutout, the keyboard */
    @JvmStatic fun resized(id: Long, width: Double, height: Double, scale: Double, safeTop: Double, safeLeft: Double, safeBottom: Double, safeRight: Double, keyboard: Double): ByteArray {
        val w = WireWriter()
        w.uvarint(10)
        w.int(id)
        w.float(width)
        w.float(height)
        w.float(scale)
        w.float(safeTop)
        w.float(safeLeft)
        w.float(safeBottom)
        w.float(safeRight)
        w.float(keyboard)
        return w.toByteArray()
    }
    /** the system's gesture of going back, as it goes: Phase is "started", "progress" or "cancelled" */
    @JvmStatic fun backGesture(id: Long, phase: String, progress: Double): ByteArray {
        val w = WireWriter()
        w.uvarint(11)
        w.int(id)
        w.string(phase)
        w.float(progress)
        return w.toByteArray()
    }
    /** a tap on iOS's status bar */
    @JvmStatic fun statusBarTapped(): ByteArray {
        val w = WireWriter()
        w.uvarint(12)
        return w.toByteArray()
    }
    /** a finger went down on a view a surface holds, which takes it */
    @JvmStatic fun viewPressed(id: Long, x: Double, y: Double): ByteArray {
        val w = WireWriter()
        w.uvarint(13)
        w.int(id)
        w.float(x)
        w.float(y)
        return w.toByteArray()
    }
    @JvmStatic fun pluginResult(req: Long, result: String, error: String, code: String): ByteArray {
        val w = WireWriter()
        w.uvarint(14)
        w.int(req)
        w.string(result)
        w.string(error)
        w.string(code)
        return w.toByteArray()
    }
    /** an event of a plugin's native code: Data is JSON */
    @JvmStatic fun pluginEvent(plugin: String, name: String, data: String): ByteArray {
        val w = WireWriter()
        w.uvarint(15)
        w.string(plugin)
        w.string(name)
        w.string(data)
        return w.toByteArray()
    }
    @JvmStatic fun networkChanged(online: Boolean, metered: Boolean): ByteArray {
        val w = WireWriter()
        w.uvarint(16)
        w.bool(online)
        w.bool(metered)
        return w.toByteArray()
    }
    @JvmStatic fun shareResult(req: Long, error: String): ByteArray {
        val w = WireWriter()
        w.uvarint(17)
        w.int(req)
        w.string(error)
        return w.toByteArray()
    }
    @JvmStatic fun menuPicked(req: Long, item: Long): ByteArray {
        val w = WireWriter()
        w.uvarint(18)
        w.int(req)
        w.int(item)
        return w.toByteArray()
    }
    @JvmStatic fun barItemClicked(id: Long, index: Long): ByteArray {
        val w = WireWriter()
        w.uvarint(19)
        w.int(id)
        w.int(index)
        return w.toByteArray()
    }
    /** the user chose tab Index */
    @JvmStatic fun tabSelected(id: Long, index: Long): ByteArray {
        val w = WireWriter()
        w.uvarint(20)
        w.int(id)
        w.int(index)
        return w.toByteArray()
